package com.example.examauth.service; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service; import com.example.examauth.repo.AttendanceRepository; import com.example.examauth.repo.FraudLogRepository; import com.example.examauth.model.Attendance; import com.example.examauth.model.FraudLog; import java.time.Instant; @Service public class AttendanceService { @Autowired private AttendanceRepository attendanceRepo; @Autowired private FraudLogRepository fraudRepo; public void markAttendance(Long examId, Long studentId, Long supervisorId){ if(!attendanceRepo.existsByExamIdAndStudentId(examId, studentId)){ Attendance a = new Attendance(); a.setExamId(examId); a.setStudentId(studentId); a.setSupervisorId(supervisorId); attendanceRepo.save(a); } } public void logFraud(Long userId, Long examId, String desc){ FraudLog f = new FraudLog(); f.setUserId(userId); f.setExamId(examId); f.setDescription(desc); f.setSeverity("high"); f.setDetectedOn(java.sql.Timestamp.from(Instant.now())); f.setEscalatedToSuperAdmin(false); fraudRepo.save(f); } }